//! Файл: settings/catalog/lost_events.rs
//! Что делает: настройки решений 333/334 (задача t155) — ни одно сообщение ядру и ни один кандидат не теряются молча:
//! сообщения адаптеров ядру при полном канале (род «деньги» и род «уведомления»), ожидание места кандидатом, проверка
//! застрявшей монеты при отставании от тиков и интервал записи журнала о потерях. Все необязательные, значений нет:
//! не заданы — поведение как раньше (потеря теперь со счётом в журнале). Ревью 333 (Б1): денежные события не теряются
//! никогда, без настройки — прежняя venue.money_events_keep удалена; Н2 — venue.info_events_max, Н9 —
//! venue.money_events_alert_ms. Отдельный файл: base.rs — общий для многих задач.
//! Кто вызывает: settings/catalog/mod.rs.
//! От чего зависит: settings/catalog/mod.rs (короткая запись d и наборы областей).
//! Настройки: это и есть их список (зеркало docs/SETTINGS.md).

use super::{G, d};
use crate::settings::schema::{Kind as K, Limit as L, SettingDef};

/// Настройки решений 333/334. Порядок — как в docs/SETTINGS.md.
#[rustfmt::skip]
pub static LOST_EVENTS: &[SettingDef] = &[
    d("Расчёт выгодности", "profit.calc_wait_ms", K::Integer, L::Positive, "мс", G, "Решение 334: кандидат, которому не нашлось места расчёта (очередь расчётов полна — ёмкость --live-buffer — или достигнут предел profit.calc_concurrency), НЕ выбрасывается, а ждёт места в памяти ядра не дольше этого срока (с момента, когда места не нашлось). Место освободилось — ждущие стартуют первыми, по порядку, раньше новых кандидатов и теневых расчётов (window.busy_calc). Ждущих не больше числа направлений (направление стоит в очереди один раз). Срок profit.calc_timeout_ms считается от старта расчёта, ожидание в него не входит (видно в замере «очередь до старта»). Срок ожидания вышел — кандидат потерян: запись журнала core.candidate_lost, следующий тик поставит направление снова. Не задана — как раньше: кандидат сразу выброшен (теперь со счётом и записью журнала core.candidate_lost)").optional(),
    d("Площадки", "venue.info_events_max", K::Integer, L::Positive, "сообщений", G, "Решение 333, ревью Н2: предел очереди «ждут места» рода «уведомления» (Notice, SendChannel) одного канала событий ядра при venue.info_events_keep = да. Очередь достигла предела — новое уведомление потеряно (счёт и запись журнала venue.core_events_lost). Не задана — без предела (очередь растёт, пока ядро не разберёт канал; глубина видна в записи venue.core_events_queue). Денежных событий предел не касается — они не теряются никогда").optional(),
    d("Площадки", "venue.money_events_alert_ms", K::Integer, L::Positive, "мс", G, "Решение 333, ревью Н9: денежное событие адаптера (очередь кошелька DEX WalletQueue, замер выхода ExitGap и др.) ждало места в канале событий ядра (канал полон) не меньше столько миллисекунд — после его доставки ядру уходит уведомление venue.money_event_delayed (что ждало и сколько; включается в «Уведомлениях»). Пока событие ждало, ядро о нём не знало (например, об остановке очереди кошелька). Не задана — уведомления нет (задержка видна в записи журнала venue.core_events_queue)").optional(),
    d("Площадки", "venue.info_events_keep", K::Bool, L::None, "да/нет", G, "Решение 333: уведомления адаптеров (Notice: исполнение DEX, налоги «не задана настройка», BingX 418, Gate «вывод FAIL»), счётчики каналов отправки (SendChannel) при полном канале событий ядра НЕ теряются: ждут места в своей очереди по порядку (позади денежных событий; предел — venue.info_events_max). «Монета не проверена» в начале цикла налогов (CoinCheck) — без очереди: ждёт места той же задачей, что и итоги проверки (итог не обгонит её). Нет или не задана — как раньше: при полном канале потеряны, но с записью журнала venue.core_events_lost. Денежные события (WalletQueue, ExitGap) от этой настройки не зависят — не теряются никогда (ревью 333, Б1)").optional(),
    d("Застрявшие монеты", "stuck.tick_lag_wake", K::Bool, L::None, "да/нет", G, "Решение 334: ожидание тика монеты застрявшей сделки («Ожидание», «Перегон») отстало от рассылки тиков ядра (пропущены тики — среди них мог быть тик этой монеты): да — проверить выгодность сразу (та же проверка, что на настоящий тик); нет или не задана — как раньше ждать следующего тика монеты. Отставание в любом случае — запись журнала core.coin_ticks_lost").optional(),
    d("Система", "log.events_lost_interval_s", K::Integer, L::Positive, "секунды", G, "Решение 334: как часто писать в журнал о потерях сообщений и кандидатов (venue.core_events_lost, core.candidate_lost, core.busy_calc — теневые расчёты, core.coin_ticks_lost, notify.core_events_lost; ревью 333 — и счёт очереди сообщений ядру venue.core_events_queue: отложено / доставлено / ждут): не чаще раза в столько секунд (первая — сразу), с числом потерь с прошлой записи и всего с запуска. Не задана — запись на 1-ю, 2-ю, 4-ю, 8-ю… потерю (как у очередей окон и эпизодов): шквал потерь даёт несколько строк, а не тысячи").optional(),
];
